19	// LinkageResult holds the outcome of a linkage evaluation.
20	type LinkageResult struct {
21		Triggered    bool   // whether linkage was attempted (had sub-items)
22		Success      bool   // whether the transition succeeded
23		TargetStatus string // the intended target status
24		Remark       string // failure reason if not success
25	}
26	
27	// Warning returns a human-readable warning string if linkage was triggered but failed.
28	func (r *LinkageResult) Warning() string {
29		if r != nil && r.Triggered && !r.Success {
30			return fmt.Sprintf("主事项状态联动失败：%s", r.Remark)
31		}
32		return ""
33	}
