35	// linkageMuMap provides per-MainItem mutexes for linkage evaluation.
36	// Bounded to maxLinkageMuMapSize entries with LRU eviction.
37	const maxLinkageMuMapSize = 1000
38	
39	var (
40		linkageMuMap  = make(map[int64]*sync.Mutex)
41		linkageAccess = make(map[int64]uint64) // mainItemBizKey -> access sequence number
42		linkageSeq    uint64                   // monotonically increasing access counter
43		linkageMapMu  sync.Mutex               // protects linkageMuMap, linkageAccess, and linkageSeq
44	)
45	
46	// getLinkageMutex returns (or creates) a mutex for the given MainItem.
47	// When the map exceeds maxLinkageMuMapSize entries, the least recently used entry is evicted.
48	func getLinkageMutex(mainItemBizKey int64) *sync.Mutex {
49		linkageMapMu.Lock()
50		defer linkageMapMu.Unlock()
51	
52		if mu, ok := linkageMuMap[mainItemBizKey]; ok {
53			linkageSeq++
54			linkageAccess[mainItemBizKey] = linkageSeq
55			return mu
56		}
57	
58		// Evict LRU entry if at capacity
59		if len(linkageMuMap) >= maxLinkageMuMapSize {
60			var oldestKey int64
61			var oldestSeq uint64
62			first := true
63			for key, seq := range linkageAccess {
64				if first || seq < oldestSeq {
65					oldestKey = key
66					oldestSeq = seq
67					first = false
68				}
69			}
70			delete(linkageMuMap, oldestKey)
71			delete(linkageAccess, oldestKey)
72		}
73	
74		mu := &sync.Mutex{}
75		linkageSeq++
76		linkageMuMap[mainItemBizKey] = mu
77		linkageAccess[mainItemBizKey] = linkageSeq
78		return mu
79	}
80	
81	// resetLinkageMuMap resets the global linkage map. Used only in tests.
82	func resetLinkageMuMap() {
83		linkageMapMu.Lock()
84		defer linkageMapMu.Unlock()
85		linkageMuMap = make(map[int64]*sync.Mutex)
86		linkageAccess = make(map[int64]uint64)
87		linkageSeq = 0
88	}
