115	func (s *mainItemService) Create(ctx context.Context, teamBizKey, pmBizKey int64, req dto.MainItemCreateReq) (*model.MainItem, error) {
116		code, err := s.mainItemRepo.NextCode(ctx, teamBizKey)
117		if err != nil {
118			return nil, err
119		}
120	
121		item := &model.MainItem{
122			BaseModel:   model.BaseModel{BizKey: snowflake.Generate()},
123			TeamKey:     teamBizKey,
124			Code:        code,
125			Title:       req.Title,
126			ItemDesc:    req.Description,
127			Priority:    req.Priority,
128			ProposerKey: pmBizKey,
129			AssigneeKey: func() *int64 {
130				if req.AssigneeKey != "" {
131					v, _ := pkg.ParseID(req.AssigneeKey)
132					return &v
133				}
134				return nil
135			}(),
136			IsKeyItem:  req.IsKeyItem,
137			ItemStatus: "pending",
138		}
139	
140		if req.StartDate != nil {
141			if t, err := dates.ParseDate(*req.StartDate); err == nil {
142				item.PlanStartDate = &t
143			}
144		}
145		if req.ExpectedEndDate != nil {
146			if t, err := dates.ParseDate(*req.ExpectedEndDate); err == nil {
147				item.ExpectedEndDate = &t
148			}
149		}
150	
151		if err := s.mainItemRepo.Create(ctx, item); err != nil {
152			if apperrors.IsMySQLDuplicateError(err) {
153				return nil, apperrors.ErrDuplicateBizKey
154			}
155			return nil, err
156		}
157		return item, nil
158	}
