160	func (s *mainItemService) Update(ctx context.Context, teamBizKey int64, itemID uint, req dto.MainItemUpdateReq) error {
161		item, err := s.mainItemRepo.FindByID(ctx, itemID)
162		if err != nil {
163			return apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
164		}
165		if item.TeamKey != teamBizKey {
166			return apperrors.ErrForbidden
167		}
168		if status.IsMainTerminal(item.ItemStatus) {
169			return apperrors.ErrTerminalMainItem
170		}
171	
172		fields := map[string]interface{}{}
173		if req.Title != nil {
174			fields["title"] = *req.Title
175		}
176		if req.Description != nil {
177			fields["item_desc"] = *req.Description
178		}
179		if req.Priority != nil {
180			fields["priority"] = *req.Priority
181		}
182		if req.AssigneeKey != nil {
183			assigneeKey, err := pkg.ParseIDPtr(req.AssigneeKey)
184			if err != nil {
185				return apperrors.ErrValidation
186			}
187			fields["assignee_key"] = assigneeKey
188		}
189		if req.IsKeyItem != nil {
190			fields["is_key_item"] = *req.IsKeyItem
191		}
192		if req.StartDate != nil {
193			fields["plan_start_date"] = *req.StartDate
194		}
195		if req.ExpectedEndDate != nil {
196			fields["expected_end_date"] = *req.ExpectedEndDate
197		}
198		if req.ActualEndDate != nil {
199			fields["actual_end_date"] = *req.ActualEndDate
200		}
201	
202		if len(fields) == 0 {
203			return nil
204		}
205	
206		return s.mainItemRepo.Update(ctx, item, fields)
207	}
