262	func (s *mainItemService) ChangeStatus(ctx context.Context, teamBizKey, callerBizKey int64, itemID uint, newStatus string) (*model.MainItem, error) {
263		item, err := s.mainItemRepo.FindByID(ctx, itemID)
264		if err != nil {
265			return nil, apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
266		}
267		if item.TeamKey != teamBizKey {
268			return nil, apperrors.ErrForbidden
269		}
270	
271		// Self-transition check
272		if newStatus == item.ItemStatus {
273			return nil, apperrors.ErrInvalidStatus
274		}
275	
276		// Validate transition
277		if !status.IsValidTransition(status.MainItemTransitions, item.ItemStatus, newStatus) {
278			return nil, apperrors.ErrInvalidStatus
279		}
280	
281		// PM-only check: reviewing -> completed/progressing requires caller == proposer
282		if item.ItemStatus == "reviewing" && (newStatus == "completed" || newStatus == "progressing") {
283			if callerBizKey != item.ProposerKey {
284				return nil, apperrors.ErrForbidden
285			}
286		}
287	
288		// Guard: cannot transition to terminal if any sub-item is non-terminal
289		if status.IsMainTerminal(newStatus) {
290			subs, err := s.subItemRepo.ListByMainItem(ctx, item.BizKey) //nolint:govet // intentional shadow: inner-block err assignment
291			if err != nil {
292				return nil, err
293			}
294			for _, sub := range subs {
295				if !status.IsSubTerminal(sub.ItemStatus) {
296					return nil, apperrors.ErrSubItemsNotTerminal
297				}
298			}
299		}
300	
301		fields := map[string]interface{}{
302			"item_status": newStatus,
303		}
304	
305		// Terminal side effects
306		if status.IsMainTerminal(newStatus) {
307			fields["completion_pct"] = float64(100)
308			now := time.Now()
309			fields["actual_end_date"] = &now
310		}
311	
312		// Capture old status before update (repo may mutate the item)
313		oldStatus := item.ItemStatus
314	
315		if err := s.mainItemRepo.Update(ctx, item, fields); err != nil { //nolint:govet // intentional shadow: inner-block err assignment
316			return nil, err
317		}
318	
319		// Record to status history
320		if err := RecordStatusChange(s.statusHistorySvc, ctx, "main_item", item.BizKey, oldStatus, newStatus, callerBizKey, 0, ""); err != nil { //nolint:govet // intentional shadow: inner-block err assignment
321			return nil, err
322		}
323	
324		// Fetch updated item
325		updated, err := s.mainItemRepo.FindByID(ctx, itemID)
326		if err != nil {
327			return nil, err
328		}
329		return updated, nil
330	}
