332	func (s *mainItemService) AvailableTransitions(ctx context.Context, teamBizKey, callerBizKey int64, itemID uint) ([]string, error) {
333		item, err := s.mainItemRepo.FindByID(ctx, itemID)
334		if err != nil {
335			return nil, apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
336		}
337		if item.TeamKey != teamBizKey {
338			return nil, apperrors.ErrForbidden
339		}
340	
341		transitions := status.GetAvailableTransitions(status.MainItemTransitions, item.ItemStatus)
342	
343		// PM-only filter: non-PM callers don't see completed/progressing when reviewing
344		if item.ItemStatus == "reviewing" && callerBizKey != item.ProposerKey {
345			filtered := make([]string, 0, len(transitions))
346			for _, t := range transitions {
347				if t != "completed" && t != "progressing" {
348					filtered = append(filtered, t)
349				}
350			}
351			return filtered, nil
352		}
353	
354		return transitions, nil
355	}
