357	// EvaluateLinkage evaluates the main-sub item linkage rules and updates MainItem status.
358	// It acquires a per-MainItem mutex to prevent race conditions.
359	func (s *mainItemService) EvaluateLinkage(ctx context.Context, mainItemBizKey, changedByBizKey int64) (*LinkageResult, error) {
360		mu := getLinkageMutex(mainItemBizKey)
361		mu.Lock()
362		defer mu.Unlock()
363	
364		mainItem, err := s.mainItemRepo.FindByBizKey(ctx, mainItemBizKey)
365		if err != nil {
366			return nil, apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
367		}
368	
369		subItems, err := s.subItemRepo.ListByMainItem(ctx, mainItemBizKey)
370		if err != nil {
371			return nil, err
372		}
373	
374		// No sub-items: no linkage triggered
375		if len(subItems) == 0 {
376			return nil, nil
377		}
378	
379		// Evaluate 5-level priority rules
380		targetStatus := evaluateLinkageTarget(subItems, mainItem.ItemStatus)
381		if targetStatus == "" || targetStatus == mainItem.ItemStatus {
382			return nil, nil
383		}
384	
385		// Check if transition is valid
386		if !status.IsValidTransition(status.MainItemTransitions, mainItem.ItemStatus, targetStatus) {
387			// Linkage failed: record intent in status history
388			remark := fmt.Sprintf("%s→%s 不允许", mainItem.ItemStatus, targetStatus)
389			_ = RecordStatusChange(s.statusHistorySvc, ctx, "main_item", mainItemBizKey, mainItem.ItemStatus, targetStatus, changedByBizKey, 1, remark)
390			return &LinkageResult{
391				Triggered:    true,
392				Success:      false,
393				TargetStatus: targetStatus,
394				Remark:       remark,
395			}, nil
396		}
397	
398		// Apply transition
399		fields := map[string]interface{}{
400			"item_status": targetStatus,
401		}
402	
403		// Terminal side effects
404		if status.IsMainTerminal(targetStatus) {
405			fields["completion_pct"] = float64(100)
406			now := time.Now()
407			fields["actual_end_date"] = &now
408		}
409	
410		oldStatus := mainItem.ItemStatus
411	
412		if err := s.mainItemRepo.Update(ctx, mainItem, fields); err != nil {
413			return nil, err
414		}
415	
416		// Record to status history (is_auto=true)
417		_ = RecordStatusChange(s.statusHistorySvc, ctx, "main_item", mainItemBizKey, oldStatus, targetStatus, changedByBizKey, 1, "")
418	
419		return &LinkageResult{
420			Triggered:    true,
421			Success:      true,
422			TargetStatus: targetStatus,
423		}, nil
424	}
425	
426	// evaluateLinkageTarget determines the target status based on 5-level priority rules.
427	// Returns empty string if no linkage rule matches.
428	func evaluateLinkageTarget(subItems []*model.SubItem, currentMainStatus string) string {
429		allTerminal := true // completed or closed
430		allClosed := true   // closed only
431		allPausingOrClosed := true
432		hasCompleted := false
433		hasBlocking := false
434		hasProgressing := false
435	
436		for _, si := range subItems {
437			s := si.ItemStatus
438			isCompleted := s == "completed"
439			isClosed := s == "closed"
440			isTerminal := isCompleted || isClosed
441			isPausing := s == "pausing"
442	
443			if !isTerminal {
444				allTerminal = false
445			}
446			if !isClosed {
447				allClosed = false
448			}
449			if !isPausing && !isClosed {
450				allPausingOrClosed = false
451			}
452			if isCompleted {
453				hasCompleted = true
454			}
455			if s == "blocking" {
456				hasBlocking = true
457			}
458			if s == "progressing" {
459				hasProgressing = true
460			}
461		}
462	
463		// Priority 1: all completed/closed + at least one completed → reviewing
464		if allTerminal && hasCompleted {
465			return "reviewing"
466		}
467	
468		// Priority 2: all closed → closed
469		if allClosed {
470			return "closed"
471		}
472	
473		// Priority 3: all pausing (or pausing + closed) → pausing
474		if allPausingOrClosed && !allClosed {
475			return "pausing"
476		}
477	
478		// Priority 4: any blocking (not all terminal) → blocking (only from pending/progressing)
479		if hasBlocking && !allTerminal {
480			if currentMainStatus == "pending" || currentMainStatus == "progressing" {
481				return "blocking"
482			}
483		}
484	
485		// Priority 5: any progressing → progressing (only from pending)
486		if hasProgressing && currentMainStatus == "pending" {
487			return "progressing"
488		}
489	
490		// AC-9: reviewing + non-terminal sub-items → revert to progressing
491		if currentMainStatus == "reviewing" && !allTerminal {
492			return "progressing"
493		}
494	
495		return ""
496	}
497	
498	// calcWeightedCompletion computes weighted average of SubItem completion values.
499	// If no sub-items, returns 0. If all weights are zero, falls back to simple average.
500	func calcWeightedCompletion(items []*model.SubItem) float64 {
501		if len(items) == 0 {
502			return 0
503		}
504	
505		var totalWeight, weightedSum float64
506		for _, si := range items {
507			totalWeight += si.Weight
508			weightedSum += si.Completion * si.Weight
509		}
510	
511		if totalWeight == 0 {
512			var sum float64
513			for _, si := range items {
514				sum += si.Completion
515			}
516			return sum / float64(len(items))
517		}
518	
519		return weightedSum / totalWeight
520	}
