47	func (r *mainItemRepo) List(ctx context.Context, teamBizKey int64, filter dto.MainItemFilter, page dto.Pagination) (*dto.PageResult[model.MainItem], error) {
48		query := r.db.WithContext(ctx).Scopes(NotDeleted).Where("team_key = ?", teamBizKey)
49	
50		// Filter out archived by default; include when filter.Archived is true
51		if !filter.Archived {
52			query = query.Where("archived_at IS NULL")
53		}
54	
55		query = applyItemFilter(query, filter.Status, filter.Priority, filter.AssigneeKey, filter.IsKeyItem)
56	
57		var total int64
58		if err := query.Model(&model.MainItem{}).Count(&total).Error; err != nil {
59			return nil, err
60		}
61	
62		// Apply pagination
63		offset, p, ps := dto.ApplyPaginationDefaults(page.Page, page.PageSize)
64		page.Page = p
65		page.PageSize = ps
66	
67		var items []model.MainItem
68		if err := query.Order("id DESC").Offset(offset).Limit(page.PageSize).Find(&items).Error; err != nil {
69			return nil, err
70		}
71	
72		return &dto.PageResult[model.MainItem]{
73			Items: items,
74			Total: total,
75			Page:  page.Page,
76			Size:  page.PageSize,
77		}, nil
78	}
