80	//nolint:dupl // same transaction shape as subItemRepo.NextSubCode; core logic extracted to nextSeqInTx
81	func (r *mainItemRepo) NextCode(ctx context.Context, teamBizKey int64) (string, error) {
82		var code string
83		err := r.db.WithContext(ctx).Transaction(func(tx *gormlib.DB) error {
84			// Increment counter first — real write acquires SQLite write lock, serializing concurrent calls.
85			if err := tx.Exec("UPDATE pmw_teams SET item_seq = item_seq + 1 WHERE biz_key = ?", teamBizKey).Error; err != nil {
86				return err
87			}
88			var team model.Team
89			if err := tx.Where("biz_key = ?", teamBizKey).First(&team).Error; err != nil {
90				return err
91			}
92	
