59	// MapNotFound maps gorm.ErrRecordNotFound and ErrNotFound to the provided domain error.
60	// Returns the original error unchanged if it is not a not-found error.
61	func MapNotFound(err error, domainErr *AppError) error {
62		if err == nil {
63			return nil
64		}
65		if stderrors.Is(err, gorm.ErrRecordNotFound) || stderrors.Is(err, ErrNotFound) {
66			return domainErr
67		}
68		return err
69	}
