71	// RespondError writes a standard error envelope. Non-AppError values fall back to ErrInternal.
72	func RespondError(c *gin.Context, err error) {
73		var appErr *AppError
74		if stderrors.As(err, &appErr) {
75			c.JSON(appErr.Status, gin.H{"code": appErr.Code, "message": appErr.Message})
76			return
77		}
78		c.JSON(ErrInternal.Status, gin.H{"code": ErrInternal.Code, "message": ErrInternal.Message})
79	}
80	
81	// RespondOK writes a standard success envelope with the given data.
82	func RespondOK(c *gin.Context, data any) {
83		c.JSON(http.StatusOK, gin.H{"code": 0, "data": data})
84	}
85	
86	// RespondCreated writes a standard success envelope with HTTP 201 status.
87	func RespondCreated(c *gin.Context, data any) {
88		c.JSON(http.StatusCreated, gin.H{"code": 0, "data": data})
89	}
90	
91	// IsMySQLDuplicateError returns true if err is a MySQL duplicate entry error (1062).
92	func IsMySQLDuplicateError(err error) bool {
93		var mysqlErr *mysql.MySQLError
94		return stderrors.As(err, &mysqlErr) && mysqlErr.Number == 1062
95	}
