5	// MainItemTransitions defines the legal status transition paths for main items.
6	var MainItemTransitions = map[string][]string{
7		"pending":     {"progressing", "closed"},
8		"progressing": {"blocking", "pausing", "reviewing", "closed"},
9		"blocking":    {"progressing"},
10		"pausing":     {"progressing", "closed"},
11		"reviewing":   {"completed", "progressing"},
12	}
13	
14	// SubItemTransitions defines the legal status transition paths for sub items.
15	var SubItemTransitions = map[string][]string{
16		"pending":     {"progressing", "closed"},
17		"progressing": {"blocking", "pausing", "completed", "closed"},
18		"blocking":    {"progressing"},
19		"pausing":     {"progressing", "closed"},
20	}
21	
22	// IsValidTransition checks whether transitioning from one status to another is allowed.
23	// Returns false for self-transitions or unknown status codes.
24	func IsValidTransition(transitions map[string][]string, from, to string) bool {
25		if from == to {
26			return false
27		}
28		targets, ok := transitions[from]
29		if !ok {
30			return false
31		}
32		return slices.Contains(targets, to)
33	}
34	
35	// GetAvailableTransitions returns the list of valid target statuses from the current status.
36	// Returns an empty slice for terminal or unknown statuses.
37	// Returns a copy to prevent mutation of the original data.
38	func GetAvailableTransitions(transitions map[string][]string, current string) []string {
39		targets, ok := transitions[current]
40		if !ok {
41			return []string{}
42		}
43		result := make([]string, len(targets))
44		copy(result, targets)
45		return result
46	}
