15	// acceptedFields maps model table names to their updatable field whitelist.
16	var acceptedFields = map[string]map[string]bool{
17		model.MainItem{}.TableName(): {"title": true, "priority": true, "item_status": true, "assignee_key": true, "completion_pct": true, "actual_end_date": true, "archived_at": true, "item_desc": true, "is_key_item": true, "plan_start_date": true, "expected_end_date": true},
18		model.SubItem{}.TableName():  {"title": true, "item_status": true, "priority": true, "assignee_key": true, "completion_pct": true, "actual_end_date": true, "item_desc": true, "plan_start_date": true, "expected_end_date": true},
19		model.User{}.TableName():     {"display_name": true},
20		model.ItemPool{}.TableName(): {"pool_status": true, "assigned_main_key": true, "assigned_sub_key": true, "assignee_key": true, "reject_reason": true, "reviewed_at": true, "reviewer_key": true, "title": true, "background": true, "expected_output": true},
21	}
22	
23	// identifiable constrains T to model types that have an ID field.
24	type identifiable interface {
25		model.MainItem | model.SubItem | model.User | model.Team | model.Role |
26			model.ProgressRecord | model.StatusHistory | model.ItemPool | model.TeamMember
27	}
28	
29	// isSoftDeletable returns true for model types that embed BaseModel (have deleted_flag).
30	// Uses a negative list: only ProgressRecord and StatusHistory return false.
31	func isSoftDeletable[T any]() bool {
32		switch any(new(T)).(type) {
33		case *model.ProgressRecord, *model.StatusHistory:
34			return false
35		default:
36			return true
37		}
38	}
39	
40	// FindByID retrieves a single record by primary key.
41	// Returns apperrors.ErrNotFound if the record does not exist.
42	// For soft-deletable types, automatically filters out soft-deleted records.
43	func FindByID[T any](db *gormlib.DB, ctx context.Context, id uint) (*T, error) {
44		var item T
45		query := db.WithContext(ctx)
46		if isSoftDeletable[T]() {
47			query = query.Where("deleted_flag = 0")
48		}
49		err := query.First(&item, id).Error
50		if err != nil {
51			if errors.Is(err, gormlib.ErrRecordNotFound) {
52				return nil, apperrors.ErrNotFound
53			}
54			return nil, err
55		}
56		return &item, nil
57	}
58	
59	// FindByIDs retrieves multiple records by their primary keys.
60	// Returns a map keyed by ID. Missing IDs are absent from the map (no error).
61	// Empty input returns an empty map with no query.
62	// For soft-deletable types, automatically filters out soft-deleted records.
63	func FindByIDs[T identifiable](db *gormlib.DB, ctx context.Context, ids []uint) (map[uint]*T, error) {
64		result := make(map[uint]*T)
65		if len(ids) == 0 {
66			return result, nil
67		}
68		query := db.WithContext(ctx)
69		if isSoftDeletable[T]() {
70			query = query.Where("deleted_flag = 0")
71		}
72		var items []*T
73		if err := query.Where("id IN ?", ids).Find(&items).Error; err != nil {
74			return nil, err
75		}
76		for _, item := range items {
77			result[getID(item)] = item
78		}
79		return result, nil
80	}
81	
82	// getID extracts the primary key from a model pointer via type switch.
83	func getID[T identifiable](v *T) uint {
84		switch item := any(v).(type) {
85		case *model.MainItem:
86			return item.ID
87		case *model.SubItem:
88			return item.ID
89		case *model.User:
90			return item.ID
91		case *model.Team:
92			return item.ID
93		case *model.Role:
94			return item.ID
95		case *model.ProgressRecord:
96			return item.ID
97		case *model.StatusHistory:
98			return item.ID
99		case *model.ItemPool:
100			return item.ID
101		case *model.TeamMember:
102			return item.ID
103		default:
104			return 0
105		}
106	}
107	
108	// UpdateFields performs a partial update on the given model instance.
109	// Fields are validated against a whitelist per entity type.
110	// Returns apperrors.ErrInvalidField for unknown field keys.
111	// Returns apperrors.ErrNotFound if the team_id check fails (zero rows affected).
112	func UpdateFields[T any](db *gormlib.DB, ctx context.Context, item *T, teamKey int64, fields map[string]any) error {
113		if len(fields) == 0 {
114			return nil
115		}
116	
117		stmt := &gormlib.Statement{DB: db}
118		_ = stmt.Parse(item)
119		tableName := stmt.Table
120		allowed, ok := acceptedFields[tableName]
121		if !ok {
122			return fmt.Errorf("%w: unsupported entity %q", apperrors.ErrInvalidField, tableName)
123		}
124		for key := range fields {
125			if !allowed[key] {
126				return fmt.Errorf("%w: %q", apperrors.ErrInvalidField, key)
127			}
128		}
129	
130		query := db.WithContext(ctx).Model(item)
131		if teamKey != 0 {
132			query = query.Where("team_key = ?", teamKey)
133		}
134		result := query.Updates(fields)
135		if result.Error != nil {
136			return result.Error
137		}
138		if result.RowsAffected == 0 {
139			return apperrors.ErrNotFound
140		}
141		return nil
142	}
