3	// ApplyPaginationDefaults sets missing pagination fields to defaults (page=1, pageSize=20)
4	// and computes the offset. Returns (offset, page, pageSize).
5	func ApplyPaginationDefaults(p, ps int) (offset, page, pageSize int) {
6		return ApplyPaginationWithDefault(p, ps, 20)
7	}
8	
9	// ApplyPaginationWithDefault sets missing pagination fields to defaults (page=1, pageSize=defaultPageSize)
10	// and computes the offset. Returns (offset, page, pageSize).
11	func ApplyPaginationWithDefault(p, ps, defaultPageSize int) (offset, page, pageSize int) {
12		page = p
13		pageSize = ps
14		if page <= 0 {
15			page = 1
16		}
17		if pageSize <= 0 {
18			pageSize = defaultPageSize
19		}
20		offset = (page - 1) * pageSize
21		return
22	}
