100	// allCodes is the lazily populated flat set of all valid permission codes.
101	var allCodes map[string]bool
102	
103	func init() {
104		allCodes = make(map[string]bool, countCodes())
105		for _, rp := range Registry {
106			for _, p := range rp.Permissions {
107				allCodes[p.Code] = true
108			}
109		}
110	}
