112	// AllCodes returns a flat map[string]bool containing every registered permission code.
113	func AllCodes() map[string]bool {
114		result := make(map[string]bool, len(allCodes))
115		for k, v := range allCodes {
116			result[k] = v
117		}
118		return result
119	}
