121	// AllCodeStrings returns a flat slice of all registered permission code strings.
122	func AllCodeStrings() []string {
123		codes := make([]string, 0, countCodes())
124		for _, rp := range Registry {
125			for _, p := range rp.Permissions {
126				codes = append(codes, p.Code)
127			}
128		}
129		return codes
