47	func (s *subItemService) Create(ctx context.Context, teamBizKey, callerBizKey int64, req dto.SubItemCreateReq) (*model.SubItem, error) {
48		mainBizKey, _ := pkg.ParseID(req.MainItemKey)
49		mainItem, err := s.mainItemSvc.GetByBizKey(ctx, mainBizKey)
50		if err != nil {
51			return nil, err
52		}
53		if status.IsMainTerminal(mainItem.ItemStatus) {
54			return nil, apperrors.ErrTerminalMainItem
55		}
56	
57		code, err := s.subItemRepo.NextSubCode(ctx, mainItem.BizKey)
58		if err != nil {
59			return nil, err
60		}
61	
62		item := &model.SubItem{
63			BaseModel:   model.BaseModel{BizKey: snowflake.Generate()},
64			TeamKey:     teamBizKey,
65			MainItemKey: mainItem.BizKey,
66			Code:        code,
67			Title:       req.Title,
68			ItemDesc:    req.Description,
69			Priority:    req.Priority,
70			AssigneeKey: func() *int64 {
71				if req.AssigneeKey != "" {
72					v, _ := pkg.ParseID(req.AssigneeKey)
73					return &v
74				}
75				return nil
76			}(),
77			ItemStatus: "pending",
78			Weight:     1.0,
79		}
80	
81		if req.StartDate != nil {
82			if t, err := dates.ParseDate(*req.StartDate); err == nil {
83				item.PlanStartDate = &t
84			}
85		}
86		if req.ExpectedEndDate != nil {
87			if t, err := dates.ParseDate(*req.ExpectedEndDate); err == nil {
88				item.ExpectedEndDate = &t
89			}
90		}
91	
92		if err := s.subItemRepo.Create(ctx, item); err != nil {
93			return nil, err
94		}
95	
96		// Trigger linkage evaluation after creating a new sub-item
97		_, _ = s.mainItemSvc.EvaluateLinkage(ctx, mainItem.BizKey, callerBizKey)
98	
99		return item, nil
100	}
