102	func (s *subItemService) Update(ctx context.Context, teamBizKey int64, itemID uint, req dto.SubItemUpdateReq) error {
103		item, err := s.subItemRepo.FindByID(ctx, itemID)
104		if err != nil {
105			return apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
106		}
107		if item.TeamKey != teamBizKey {
108			return apperrors.ErrForbidden
109		}
110	
111		fields := map[string]interface{}{}
112		if req.Title != nil {
113			fields["title"] = *req.Title
114		}
115		if req.Description != nil {
116			fields["item_desc"] = *req.Description
117		}
118		if req.Priority != nil {
119			fields["priority"] = *req.Priority
120		}
121		if req.AssigneeKey != nil {
122			assigneeKey, err := pkg.ParseIDPtr(req.AssigneeKey)
123			if err != nil {
124				return apperrors.ErrValidation
125			}
126			fields["assignee_key"] = assigneeKey
127		}
128		if req.StartDate != nil {
129			fields["plan_start_date"] = *req.StartDate
130		}
131		if req.ExpectedEndDate != nil {
132			fields["expected_end_date"] = *req.ExpectedEndDate
133		}
134	
135		if len(fields) == 0 {
136			return nil
137		}
138	
139		return s.subItemRepo.Update(ctx, item, fields)
140	}
