142	func (s *subItemService) ChangeStatus(ctx context.Context, teamBizKey, callerBizKey int64, itemID uint, newStatus string) (*SubItemChangeResult, error) {
143		item, err := s.subItemRepo.FindByID(ctx, itemID)
144		if err != nil {
145			return nil, apperrors.MapNotFound(err, apperrors.ErrItemNotFound)
146		}
147		if item.TeamKey != teamBizKey {
148			return nil, apperrors.ErrForbidden
149		}
150	
151		if !status.IsValidTransition(status.SubItemTransitions, item.ItemStatus, newStatus) {
152			return nil, apperrors.ErrInvalidStatus
153		}
154	
155		fields := map[string]interface{}{
156			"item_status": newStatus,
157		}
158	
159		// Terminal side effects: force completion=100 and set actual_end_date
160		if newStatus == "completed" || newStatus == "closed" {
161			fields["completion_pct"] = float64(100)
162			now := time.Now()
163			fields["actual_end_date"] = &now
164		}
165	
166		// Capture old status before update (repo may mutate the item)
167		oldStatus := item.ItemStatus
168	
169		if err := s.subItemRepo.Update(ctx, item, fields); err != nil { //nolint:govet // intentional shadow: inner-block err assignment
170			return nil, err
171		}
172	
173		// After terminal transition, recalculate parent MainItem completion
174		if newStatus == "completed" || newStatus == "closed" {
175			if err := s.mainItemSvc.RecalcCompletion(ctx, item.MainItemKey); err != nil { //nolint:govet // intentional shadow: inner-block err assignment
176				return nil, err
177			}
178		}
179	
180		// Record to status history
181		if err := RecordStatusChange(s.statusHistorySvc, ctx, "sub_item", item.BizKey, oldStatus, newStatus, callerBizKey, 0, ""); err != nil { //nolint:govet // intentional shadow: inner-block err assignment
182			return nil, err
183		}
184	
185		// Evaluate linkage after status change
186		linkageResult, _ := s.mainItemSvc.EvaluateLinkage(ctx, item.MainItemKey, callerBizKey)
187	
188		// Fetch updated item
189		updated, err := s.subItemRepo.FindByID(ctx, itemID)
190		if err != nil {
191			return nil, err
192		}
193	
194		return &SubItemChangeResult{SubItem: updated, LinkageResult: linkageResult}, nil
195	}
